/**
 * Generates test-files/generated/sample-garden-build.xml: a small, entirely
 * fictional Microsoft Project XML (MSPDI) plan used to test the viewer.
 * It exercises summaries (3 levels), milestones, all four link types,
 * positive and negative lags, partial % complete and resource assignments.
 * Generated by this repo, so it is covered by the repo's MIT licence.
 *
 *   npm run gen:sample
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const out = path.join(here, '../test-files/generated/sample-garden-build.xml');
const START = Date.UTC(2026, 10, 2); // Mon 2 Nov 2026

/** Working day n (0-based, Mon-Fri) -> UTC ms at 08:00, or 17:00 for an end. */
function wd(n, end = false) {
  let d = START;
  let count = 0;
  while (count < n || [0, 6].includes(new Date(d).getUTCDay())) {
    d += 86400000;
    if (![0, 6].includes(new Date(d).getUTCDay())) count++;
  }
  return d + (end ? 17 : 8) * 3600000;
}
const iso = (ms) => new Date(ms).toISOString().slice(0, 19);

const resources = [
  { uid: 1, name: 'Project Lead', initials: 'PL', group: 'Sample team', rate: 45 },
  { uid: 2, name: 'Garden Designer', initials: 'GD', group: 'Sample team', rate: 40 },
  { uid: 3, name: 'Builder', initials: 'BU', group: 'Contractor', rate: 35 },
  { uid: 4, name: 'Landscaper', initials: 'LA', group: 'Contractor', rate: 32 },
  { uid: 5, name: 'Electrician', initials: 'EL', group: 'Contractor', rate: 50 },
  { uid: 6, name: 'Volunteer', initials: 'VO', group: 'Community', rate: 0 },
  { uid: 7, name: 'Timber', initials: 'TI', group: 'Materials', rate: 12, material: true },
];
// [uid, name, level, startWD, durWD, %complete, preds [uid, type, lagDays], assignments [resUid, units]]
const T = [
  [1, 'Planning', 1],
  [2, 'Kick-off meeting', 2, 0, 1, 100, [], [[1, 1], [2, 1]]],
  [3, 'Survey the site', 2, 1, 2, 100, [[2, 'FS', 0]], [[1, 1], [3, 1]]],
  [4, 'Draft the garden design', 2, 3, 4, 60, [[3, 'FS', 0]], [[2, 1]]],
  [5, 'Order materials', 2, 5, 2, 0, [[4, 'SS', 2]], [[1, 0.5], [7, 40]]],
  [6, 'Design approved', 2, 7, 0, 0, [[4, 'FS', 0]], []],
  [7, 'Build', 1],
  [8, 'Clear the ground', 2, 7, 3, 0, [[6, 'FS', 0]], [[3, 1], [4, 1]]],
  [9, 'Lay foundations', 2, 10, 4, 0, [[8, 'FS', 0]], [[3, 1]]],
  [10, 'Raised beds', 2],
  [11, 'Build bed frames', 3, 12, 3, 0, [[9, 'SS', 2], [5, 'FS', 0]], [[3, 1], [7, 60]]],
  [12, 'Fill beds with soil', 3, 15, 2, 0, [[11, 'FS', 0]], [[4, 1]]],
  [13, 'Paths and paving', 2, 14, 4, 0, [[9, 'FS', 0]], [[3, 0.5]]],
  [14, 'Install lighting', 2, 16, 3, 0, [[13, 'FF', 1]], [[5, 1]]],
  [15, 'Planting', 1],
  [16, 'Plant shrubs and herbs', 2, 17, 2, 0, [[12, 'FS', 0]], [[4, 1], [6, 1]]],
  [17, 'Set up watering rota', 2, 17, 1, 0, [[16, 'SS', 0]], [[6, 1]]],
  [18, 'Handover to the community', 1, 20, 0, 0, [[16, 'FS', 1], [14, 'FS', 0]], [[1, 1]]],
  [19, 'Snagging walk-round', 1, 19, 1, 0, [[18, 'SF', 0], [17, 'FS', -1]], [[1, 1], [3, 1]]],
];
const LINK = { FF: 0, FS: 1, SF: 2, SS: 3 };

const tasks = T.map(([uid, name, level, s, d, pct, preds, asg]) => ({ uid, name, level, s, d, pct, preds: preds || [], asg: asg || [], summary: s === undefined }));
// Summary dates and outline numbers.
const counters = [];
for (let i = 0; i < tasks.length; i++) {
  const t = tasks[i];
  counters.length = t.level;
  counters[t.level - 1] = (counters[t.level - 1] || 0) + 1;
  t.outline = counters.join('.');
  if (!t.summary) {
    t.start = wd(t.s);
    t.finish = t.d === 0 ? wd(t.s) : wd(t.s + t.d - 1, true);
    if (t.d === 0) t.finish = t.start = wd(t.s - 1, true);
  }
}
for (let i = tasks.length - 1; i >= 0; i--) {
  const t = tasks[i];
  if (!t.summary) continue;
  const kids = [];
  for (let j = i + 1; j < tasks.length && tasks[j].level > t.level; j++) kids.push(tasks[j]);
  t.start = Math.min(...kids.map((k) => k.start));
  t.finish = Math.max(...kids.map((k) => k.finish));
  const done = kids.filter((k) => !k.summary);
  t.pct = Math.round(done.reduce((a, k) => a + k.pct * k.d, 0) / Math.max(1, done.reduce((a, k) => a + k.d, 0)));
}
function workdaysBetween(a, b) {
  let n = 0;
  for (let d = Date.UTC(new Date(a).getUTCFullYear(), new Date(a).getUTCMonth(), new Date(a).getUTCDate()); d <= b; d += 86400000) {
    if (![0, 6].includes(new Date(d).getUTCDay())) n++;
  }
  return n;
}
const hoursBetween = (t) => (t.summary ? null : t.d * 8);
const dur = (h) => `PT${h}H0M0S`;

const x = [];
x.push('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>');
x.push('<Project xmlns="http://schemas.microsoft.com/project">');
x.push('  <SaveVersion>14</SaveVersion><Name>sample-garden-build.xml</Name><Title>Sample: Community Garden Build (fictional)</Title>');
x.push('  <Author>MS Project Viewer test generator</Author><Company>Example Ltd (fictional)</Company>');
x.push(`  <StartDate>${iso(wd(0))}</StartDate><FinishDate>${iso(Math.max(...tasks.map((t) => t.finish)))}</FinishDate>`);
x.push(`  <StatusDate>${iso(wd(6, true))}</StatusDate><ScheduleFromStart>1</ScheduleFromStart><CurrencySymbol>£</CurrencySymbol><CurrencyCode>GBP</CurrencyCode>`);
x.push('  <CalendarUID>1</CalendarUID><MinutesPerDay>480</MinutesPerDay><MinutesPerWeek>2400</MinutesPerWeek><DaysPerMonth>20</DaysPerMonth>');
x.push('  <Calendars><Calendar><UID>1</UID><Name>Standard</Name><IsBaseCalendar>1</IsBaseCalendar></Calendar></Calendars>');
x.push('  <Tasks>');
x.push(`    <Task><UID>0</UID><ID>0</ID><Name>Sample: Community Garden Build (fictional)</Name><OutlineNumber>0</OutlineNumber><OutlineLevel>0</OutlineLevel><Summary>1</Summary><Start>${iso(wd(0))}</Start><Finish>${iso(Math.max(...tasks.map((t) => t.finish)))}</Finish></Task>`);
tasks.forEach((t, i) => {
  const h = hoursBetween(t);
  const spanH = t.summary ? workdaysBetween(t.start, t.finish) * 8 : h;
  x.push('    <Task>');
  x.push(`      <UID>${t.uid}</UID><ID>${i + 1}</ID><Name>${t.name}</Name><Type>${t.summary ? 1 : 0}</Type><IsNull>0</IsNull>`);
  x.push(`      <WBS>${t.outline}</WBS><OutlineNumber>${t.outline}</OutlineNumber><OutlineLevel>${t.level}</OutlineLevel><Priority>500</Priority>`);
  x.push(`      <Start>${iso(t.start)}</Start><Finish>${iso(t.finish)}</Finish><Duration>${dur(spanH)}</Duration><DurationFormat>7</DurationFormat>`);
  x.push(`      <Work>${dur(h ?? 0)}</Work><Milestone>${t.d === 0 ? 1 : 0}</Milestone><Summary>${t.summary ? 1 : 0}</Summary><Critical>0</Critical>`);
  x.push(`      <PercentComplete>${t.pct || 0}</PercentComplete><Active>1</Active><Manual>0</Manual><ConstraintType>0</ConstraintType><CalendarUID>-1</CalendarUID>`);
  if (t.uid === 4) x.push('      <Notes>Fictional sample note: design covers six raised beds, two paths and solar lighting.</Notes>');
  for (const [p, type, lag] of t.preds) {
    x.push(`      <PredecessorLink><PredecessorUID>${p}</PredecessorUID><Type>${LINK[type]}</Type><CrossProject>0</CrossProject><LinkLag>${lag * 480 * 10}</LinkLag><LagFormat>7</LagFormat></PredecessorLink>`);
  }
  x.push('    </Task>');
});
x.push('  </Tasks>');
x.push('  <Resources>');
x.push('    <Resource><UID>0</UID><ID>0</ID><Type>1</Type><IsNull>0</IsNull></Resource>');
for (const r of resources) {
  x.push(`    <Resource><UID>${r.uid}</UID><ID>${r.uid}</ID><Name>${r.name}</Name><Type>${r.material ? 0 : 1}</Type><IsNull>0</IsNull><Initials>${r.initials}</Initials><Group>${r.group}</Group>${r.material ? '<MaterialLabel>m</MaterialLabel>' : '<MaxUnits>1.00</MaxUnits>'}<StandardRate>${r.rate}</StandardRate><StandardRateFormat>${r.material ? 7 : 2}</StandardRateFormat></Resource>`);
}
x.push('  </Resources>');
x.push('  <Assignments>');
let a = 0;
for (const t of tasks) {
  for (const [r, units] of t.asg) {
    const res = resources.find((y) => y.uid === r);
    const work = res.material ? 0 : (t.d || 0) * 8 * units;
    x.push(`    <Assignment><UID>${++a}</UID><TaskUID>${t.uid}</TaskUID><ResourceUID>${r}</ResourceUID><Units>${units}</Units><Work>${dur(work)}</Work><Start>${iso(t.start)}</Start><Finish>${iso(t.finish)}</Finish></Assignment>`);
  }
}
x.push('  </Assignments>');
x.push('</Project>');
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, `${x.join('\n')}\n`);
console.log(`wrote ${path.relative(process.cwd(), out)} (${tasks.length} tasks)`);
